"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Plan and render one split of P1 v0.4 (plan 4, 5.5-5.6): units -> versions -> an 8 s window at each decision point.

Counts per split (plan 5.6, 4.8, 4.9); half phone and half door versions, doorbell and knock half each; S-move half
with the visitor speaking; test and replication take half of S-move and episode door sounds from Freesound (post-2023,
reported by source). Recording-group caps (plan 5.6): dev 30%, test and replication 15% of a part's units of that
class, never below 1/number of groups. Train: draws 0-11 of the single-line parts and renders 0-3 of the episodes.

Planning (cheap, seeded) runs in the main process; building (TTS timing) and rendering run in worker processes. A unit
whose build fails (for example the assistant would finish before the decision point) is replaced in the next round,
until every count is met (at most 6 rounds). Writes data/p1v4/render/<split>[_dDD]/: <unit>_<version>_p<k>.wav (8 s
windows), <unit>_full.flac (episodes, for B3) and meta.jsonl (one row per unit version). For test and replication only
automatic checks are run and a seal is printed; nobody looks at the content (plan 8.5).
usage: python -I scripts/p1v4_render_split.py <split> [--draw D] [--workers N] [--limit N] [--parts p1,p2]
"""
import argparse
import hashlib
import json
import os
import sys
import traceback
from collections import Counter, defaultdict
from multiprocessing import Pool

for _v in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS"):
    os.environ.setdefault(_v, "1")

import numpy as np  # noqa: E402
import soundfile as sf  # noqa: E402

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_units as U  # noqa: E402

FLOORS = ["D", "Dk", "HE", "HS", "barge", "quiet"]
COUNTS = {
    "train": {"r_hear": 300, "r_react": 300, "s_react": 300, "s_move": 300, "floor": 300},
    "dev": {"r_hear": 200, "r_react": 150, "s_react": 150, "s_move": 150, "floor": 100},
    "test": {"r_hear": 600, "r_react": 400, "s_react": 400, "s_move": 400, "floor": 300, "report": 300},
}
COUNTS["replication"] = COUNTS["test"]
CAP = {"train": 1.0, "dev": 0.30, "test": 0.15, "replication": 0.15}
# Cap trim settings per split (cap_excess). Dev and test were trimmed to the strict cap with door sounds pooled across
# sources (commit 4c7a215). Replication is trimmed to the leak check's measure (2026-11-15, after two renders that did
# not converge): tolerance 0.05, because several of its recording types have few groups (footsteps 4, cupboard and
# drawer 4, floor doorbell 5, phone 6), where the cap is the even split that whole units and the uncapped
# new-recording units cannot meet exactly; and door sounds typed by source (p1v4_units.cap_type), as the planner caps
# them, because its FSD50K doors are 3 usable groups that carry about 500 S-move units.
TRIM = {"replication": {"tol": 0.05, "door_by_source": True}}
N_UNSEEN = 100


class Maker:
    def __init__(self, tag, n, fn):
        self.tag, self.n, self.fn, self.ok, self.tries = tag, n, fn, 0, 0


def makers_for(split, A, cap, limit=None, parts=None):
    # every planner lambda binds its own n (n=n): a closure would read n's last value (fixed 2026-11-15; the
    # dev and test renders before the fix planned with caps from that last value, 100)
    C = COUNTS[split]
    want = (lambda p: parts is None or p in parts)
    lim = (lambda n: min(n, limit) if limit else n)
    half = lambda i: "phone" if i % 2 == 0 else "door"                         # noqa: E731
    flip = (lambda r, k: A.flip[k]["common"][int(r.integers(len(A.flip[k]["common"])))])
    test_like = split in ("test", "replication")
    ms = []
    if want("r_hear"):
        n = lim(C["r_hear"])
        ms.append(Maker("rhear", n, lambda r, ci, i, n=n: U.plan_r_hear(r, A, ci, half(i), flip(r, half(i)), n // 2, cap)))
    if want("r_react"):
        n = lim(C["r_react"])
        ms.append(Maker("rreact", n, lambda r, ci, i, n=n: U.plan_r_react(r, A, ci, half(i), n // 2, cap)))
    if want("s_react"):
        n = lim(C["s_react"])
        ms.append(Maker("sreact", n, lambda r, ci, i, n=n: U.plan_s_react(r, A, ci, half(i), n // 2, cap)))
    if want("s_move"):
        n = lim(C["s_move"])
        ms.append(Maker("smove", n, lambda r, ci, i, n=n: U.plan_s_move(
            r, A, ci, n // (2 if test_like else 1), cap,
            door_source="freesound" if test_like and i % 2 == 1 else "fsd50k")))
    if want("floor"):
        n = lim(C["floor"])
        for w in FLOORS:
            ms.append(Maker(f"floor{w}", n, lambda r, ci, i, w=w, n=n: U.plan_floor(
                r, A, ci, {"HE": f"HE_{half(i)}", "HS": f"HS_{half(i)}"}.get(w, w), n, cap)))
    if want("report") and "report" in C:
        n = lim(C["report"])
        for w in ("F3", "B2"):
            ms.append(Maker(f"rep{w}", n, lambda r, ci, i, w=w, n=n: U.plan_report(r, A, ci, w, n, cap)))
    if test_like and want("unseen"):
        n = lim(N_UNSEEN)
        tonly = A.flip["phone"]["test_only"]
        newp = (lambda i: A.new["phone"] if half(i) == "phone" else A.new["doorbell"] + A.new["knock"])
        ms += [
            Maker("rhear_tonly", n, lambda r, ci, i, n=n: U.plan_r_hear(r, A, ci, "phone", tonly[int(r.integers(len(
                tonly)))], n, cap, subset="test_only_phrase")),
            Maker("rhear_piper", n, lambda r, ci, i, n=n: U.plan_r_hear(r, A, ci, half(i), flip(r, half(i)), n, cap,
                                                                   subset="piper", engine="piper")),
            Maker("rhear_vib", n, lambda r, ci, i, n=n: U.plan_r_hear(r, A, ci, "phone", flip(r, "phone"), n, cap,
                                                                 subset="vibration", ev_paths=A.clips.get(
                                                                     "vibration", []), ev_cls="vibration")),
            Maker("rhear_new", n, lambda r, ci, i, n=n: U.plan_r_hear(r, A, ci, half(i), flip(r, half(i)), n, None,
                                                                 subset="new_rec", ev_paths=newp(i),
                                                                 ev_cls="phone" if half(i) == "phone" else None))]
        for tag, plan in (("rreact", U.plan_r_react), ("sreact", U.plan_s_react)):
            ms.append(Maker(f"{tag}_piper", n, lambda r, ci, i, plan=plan, n=n: plan(r, A, ci, half(i), n, cap,
                                                                                subset="piper", engine="piper")))
            ms.append(Maker(f"{tag}_new", n, lambda r, ci, i, plan=plan, n=n: plan(r, A, ci, half(i), n, None,
                                                                              subset="new_rec", ev_paths=newp(i))))
        ms += [Maker("smove_piper", n, lambda r, ci, i, n=n: U.plan_s_move(r, A, ci, n, cap, subset="piper",
                                                                      engine="piper")),
               Maker("smove_new", n, lambda r, ci, i, n=n: U.plan_s_move(r, A, ci, n, None, subset="new_rec",
                                                                    ev_paths=A.new["doorbell"] + A.new["knock"])),
               Maker("sreact_echo", n, lambda r, ci, i, n=n: U.plan_s_react(r, A, ci, half(i), n, cap, subset="echo",
                                                                       echo=True)),
               Maker("smove_echo", n, lambda r, ci, i, n=n: U.plan_s_move(r, A, ci, n, cap, subset="echo", echo=True))]
    return ms


def key_totals(split, A, limit, parts, draw, order):
    """Units per cap key in this split, the denominator of plan 5.6's shares as the leak check measures them (the units
    of a part that use a recording type, main set and subsets pooled). Each maker plans its units once with a capper
    that never refuses (same seeds and conversations as the real planning) and every key a planned unit uses counts
    once. Without this, a key shared by several makers (the main set and its subsets, or the six floor checks) was
    capped by each maker's own count, and S-move's half count (meant for the door sound, which is split by source)
    capped every S-move recording."""
    probe = U.Capper(1e9)
    tot = Counter()
    for m in makers_for(split, A, probe, limit, parts):
        got = 0
        while got < m.n and m.tries < 30 * m.n + 200:
            ci = order[m.tries % len(order)]
            rng = np.random.default_rng(U.seed_of(split, draw, m.tag, m.tries))
            probe.log = []
            s = m.fn(rng, ci, m.tries)
            m.tries += 1
            if s is not None:
                tot.update({k for k, _ in probe.log})
                got += 1
    return dict(tot)


def plan_round(makers, split, draw, order, cap):
    specs = []
    for m in makers:
        need, k = m.n - m.ok, 0
        while k < need and m.tries < 30 * m.n + 200:
            ci = order[m.tries % len(order)]
            rng = np.random.default_rng(U.seed_of(split, draw, m.tag, m.tries))
            cap.log = []
            s = m.fn(rng, ci, m.tries)
            m.tries += 1
            if s is None:
                cap.release(cap.log)                       # a partial pick that came to nothing gives its uses back
                continue
            s["unit"] = U.safe(f"{split}_d{draw:02d}_{m.tag}_{m.tries:05d}")
            s["_tag"] = m.tag
            s["_cap_used"] = list(cap.log)
            specs.append(s)
            k += 1
    return specs


def episode_specs(split, draw, A, cap, limit):
    """Plans every kept episode of the split (and, for test and replication, the Piper-voice copies of the first
    N_UNSEEN main-prompt episodes). Only the recordings a script uses are picked; caps count, per recording type, the
    episodes that use it (as the leak check measures); a failed pick gives its uses back and the next of 20 seeds is
    tried."""
    chk_path = "results/step0_v04/episode_check.json"
    if not os.path.exists(chk_path):
        print("no checked episodes yet; skipped", flush=True)
        return []
    kept = set(json.load(open(chk_path, encoding="utf-8"))["kept"])
    plans = {s["episode"]: s for f in ("data/episodes_v04/plan.json", "data/episodes_v04/plan2.json")
             if os.path.exists(f) for s in json.load(open(f, encoding="utf-8"))}
    eps = U.load_episode_scripts()
    ids = sorted(e for e in kept if plans[e]["split"] == split)          # regenerated scripts keep their episode id
    if limit:
        ids = ids[:limit]
    jobs = []                                                            # (episode, door source, subset, engine)
    for i, eid in enumerate(ids):
        src = "freesound" if split in ("test", "replication") and i % 2 == 1 else "fsd50k"
        jobs.append((eid, src, "prompt2" if plans[eid].get("prompt_version") == 2 else None, None))
    if split in ("test", "replication"):
        for eid in [e for e in ids if plans[e].get("prompt_version") != 2][:limit or N_UNSEEN]:
            jobs.append((eid, "fsd50k", "piper", "piper"))
    totals = Counter(k for eid, src, _, _ in jobs for k in U.episode_cap_keys(plans[eid], eps[eid], src))
    out, failed = [], 0
    for eid, src, subset, engine in jobs:
        tag = "episode" if engine is None else "episode_piper"
        for tries in range(20):
            rng = np.random.default_rng(U.seed_of(split, draw, tag, eid, tries))
            cap.log = []
            s = U.plan_episode(rng, A, plans[eid], eps[eid], totals, cap, door_source=src, engine=engine,
                               subset=subset)
            if s is None:
                cap.release(cap.log)                       # a partial pick that came to nothing gives its uses back
                continue
            s["_cap_used"] = list(cap.log)
            s["unit"] = U.safe(f"{split}_d{draw:02d}_ep_{eid}" + ("_piper" if engine == "piper" else ""))
            out.append(s)
            break
        else:
            failed += 1
    print(f"episodes planned {len(out)} of {len(jobs)} (no recordings within the caps: {failed})", flush=True)
    return out


_A = {}


def render_one(args):
    spec, out_dir = args
    try:
        split = spec["unit"].split("_d")[0]
        if split not in _A:
            _A[split] = U.Assets(split)
        A = _A[split]
        tls = U.BUILDERS[spec["part"]](spec, A)
        if tls is None:
            return spec.get("_tag"), None, ("release", spec.get("_cap_used", []))
        audio, gain_db = U.render_versions(spec, tls, A)
        rows = []
        for v, tl in tls.items():
            wins = U.windows(audio[v], tl.points)
            pts = []
            for k, (p, w) in enumerate(zip(tl.points, wins)):
                path = os.path.join(out_dir, f"{spec['unit']}_{v}_p{k}.wav").replace("\\", "/")
                sf.write(path, w, U.SR, subtype="PCM_16")
                pts.append({**p, "k": k, "window": path,
                            "sha256": hashlib.sha256(open(path, "rb").read()).hexdigest()})
            full = None
            if spec["part"] == "episode":
                full = os.path.join(out_dir, f"{spec['unit']}_full.flac").replace("\\", "/")
                sf.write(full, audio[v], U.SR, format="FLAC", subtype="PCM_16")
            groups = sorted({A.group.get(s.get("path")) for s in tl.src if s.get("path") in A.group})
            keep = {k: spec[k] for k in spec if k not in ("turns", "_assistant_text")}
            rows.append({"unit": spec["unit"], "version": v, "part": spec["part"], "subset": spec.get("subset"),
                         "spec": keep, "sources": tl.src, "assistant": tl.assistant, "points": pts, "groups": groups,
                         "full": full, "gain_db": gain_db, "peak": round(float(np.abs(audio[v]).max()) / 32767, 4),
                         "dur_s": round(len(audio[v]) / U.SR, 3)})
        return spec.get("_tag"), rows, None
    except Exception:  # noqa: BLE001
        return spec.get("_tag"), None, f"{spec.get('unit')}: {traceback.format_exc()[-600:]}"


def cap_excess(rows, A, share, tol=0.0, door_by_source=False):
    """Plan 5.6 caps after building, measured as the leak check measures them: per part and recording type
    (p1v4_units.cap_type), among the part's units that use the type, the share that uses one recording group is at
    most max(share, 1/groups) + tol (TRIM; the leak check uses + 0.05 and door sounds by source). Build failures are
    not even across types (an S-move doorbell rings longer than a knock, so the walk more often ends after the assistant
    has finished), so the planner's denominators can shrink after planning. Returns the units to replace (the fewest
    needed; the last by unit id, that is by maker tag, then plan order) and the (part, group) pairs to close.
    Single-line parts only (an episode cannot be replaced; the leak check covers episodes)."""
    if share >= 1:
        return set(), set()
    use = defaultdict(lambda: defaultdict(set))
    for r in rows:
        if r["part"] == "episode" or not (r["version"] == "1" or r["part"] in ("s_move", "s_react", "r_hear")):
            continue
        for s in r["sources"]:
            if s.get("path") in A.group:
                use[(r["part"], U.cap_type(s, A, door_by_source))][A.group[s["path"]]].add(r["unit"])
    drop, block = set(), set()
    for (part, cls), groups in sorted(use.items()):
        users = set().union(*groups.values())
        lim = max(share, 1.0 / len(groups)) + tol
        for g, us in sorted(groups.items()):
            over = len(us) - lim * len(users)
            if lim < 1 and over > 1e-9:
                drop |= set(sorted(us)[-int(np.ceil(over / (1 - lim) - 1e-9)):])
                block.add((part, g))
    return drop, block


def trim_units(rows, drop, block, cap, by_tag):
    """Removes the dropped units (rows and files), gives their cap uses back, lets their makers plan replacements and
    closes the over-share groups of their part to further picks."""
    specs = {}
    for r in rows:
        if r["unit"] in drop:
            specs[r["unit"]] = r["spec"]
            for p in r["points"]:
                if os.path.exists(p["window"]):
                    os.remove(p["window"])
            if r.get("full") and os.path.exists(r["full"]):
                os.remove(r["full"])
    for sp in specs.values():
        cap.release(sp.get("_cap_used", []))
        if sp.get("_tag") in by_tag:
            by_tag[sp["_tag"]].ok -= 1
    keys = {k for k, _ in cap.count} | set(cap.totals)
    for part, g in block:
        for k in keys:
            if k.startswith(part + ":"):
                cap.count[(k, g)] = 10 ** 9
    return [r for r in rows if r["unit"] not in drop]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("split")
    ap.add_argument("--draw", type=int, default=0)
    ap.add_argument("--workers", type=int, default=8)
    ap.add_argument("--limit", type=int, default=None)
    ap.add_argument("--parts", default=None)
    a = ap.parse_args()
    parts = set(a.parts.split(",")) if a.parts else None
    A = U.Assets(a.split)
    cap = U.Capper(CAP[a.split])
    order = [int(i) for i in np.random.default_rng(U.seed_of("order", a.split, a.draw)).permutation(len(A.convs))]
    cap.totals = key_totals(a.split, A, a.limit, parts, a.draw, order)
    print("cap totals:", {k: v for k, v in sorted(cap.totals.items())}, flush=True)
    makers = makers_for(a.split, A, cap, a.limit, parts)
    by_tag = {m.tag: m for m in makers}
    out_dir = f"data/p1v4/render/{a.split}" + (f"_d{a.draw:02d}" if a.split == "train" else "")
    if a.limit:
        out_dir += "_sample"
    os.makedirs(out_dir, exist_ok=True)
    rows, errors, ep_dropped = [], [], 0
    ep = episode_specs(a.split, a.draw, A, cap, a.limit) if parts is None or "episode" in parts else []
    rnd = 0
    with Pool(a.workers) as pool:
        for trim in range(6):
            for _ in range(10):
                specs = plan_round(makers, a.split, a.draw, order, cap) + (ep if rnd == 0 else [])
                if not specs:
                    break
                print(f"round {rnd}: {len(specs)} units", flush=True)
                for k, (tag, r, err) in enumerate(pool.imap_unordered(render_one, [(s, out_dir) for s in specs],
                                                                     chunksize=2)):
                    if r:
                        rows += r
                        if tag in by_tag:
                            by_tag[tag].ok += 1
                    if isinstance(err, tuple) and err[0] == "release":    # the build failed: give the cap uses back
                        cap.release(err[1])
                        if tag is None:                                   # an episode with no fitting timeline
                            ep_dropped += 1
                    elif err:
                        errors.append(err)
                    if k % 500 == 0:
                        print(f"  rendered {k}/{len(specs)}", flush=True)
                rnd += 1
            drop, block = cap_excess(rows, A, CAP[a.split], **TRIM.get(a.split, {}))
            if not drop:
                break
            print(f"cap trim {trim}: {len(drop)} units over their group's share replaced; closed {sorted(block)}",
                  flush=True)
            rows = trim_units(rows, drop, block, cap, by_tag)
    short = {m.tag: (m.ok, m.n) for m in makers if m.ok < m.n}
    meta_path = os.path.join(out_dir, "meta.jsonl")
    done_parts = {r["part"] for r in rows} | ({"episode"} if ep else set())
    if os.path.exists(meta_path) and parts is not None:   # merge: replace only the parts rendered now
        old = [json.loads(line) for line in open(meta_path, encoding="utf-8")]
        new_units = {r["unit"] for r in rows}
        for r in old:
            if r["part"] in done_parts and r["unit"] not in new_units:
                for p in r["points"]:
                    if os.path.exists(p["window"]):
                        os.remove(p["window"])
                if r.get("full") and os.path.exists(r["full"]):
                    os.remove(r["full"])
        rows += [r for r in old if r["part"] not in done_parts]
    rows.sort(key=lambda r: (r["unit"], r["version"]))
    with open(meta_path, "w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False, default=str) + "\n")
    n_win = sum(len(r["points"]) for r in rows)
    bad = [r["unit"] for r in rows if r["peak"] > 0.985]
    seal = hashlib.sha256("".join(sorted(p["sha256"] for r in rows for p in r["points"])).encode()).hexdigest()
    print(f"units {len({r['unit'] for r in rows})}, versions {len(rows)}, windows {n_win}, peak > 0.985: {len(bad)}, "
          f"errors {len(errors)}, short {short}, episodes without a fitting timeline {ep_dropped} of {len(ep)}; "
          f"seal {seal}")
    for e in errors[:5]:
        print("ERROR", e)


if __name__ == "__main__":
    main()
